public enum DivideStatus { Ok, DivideByZero, Overflow }

class Program
{
    static void Main()
    {
        string line;
        while ((line = Console.ReadLine()) != null)
        {
            var parts = line.Split(' ');
            int a = int.Parse(parts[0]);
            int b = int.Parse(parts[1]);
            var result = Solution.SafeDivide(a, b);
            switch (result.Status)
            {
                case DivideStatus.Ok:
                    Console.WriteLine("OK " + result.Value);
                    break;
                case DivideStatus.DivideByZero:
                    Console.WriteLine("DIVIDE_BY_ZERO");
                    break;
                case DivideStatus.Overflow:
                    Console.WriteLine("OVERFLOW");
                    break;
            }
        }
    }
}

