"""Random (a, b) pairs, weighted towards the two special cases and the
values immediately next to them, alongside ordinary divisions."""

INT_MIN = -2147483648
INT_MAX = 2147483647


def generate(rng, count):
    builders = (_ordinary, _near_zero_divisor, _near_overflow)
    return [builders[i % len(builders)](rng, i + 1) for i in range(count)]


def _case(name, rows, description=""):
    lines = ["%d %d" % row for row in rows]
    return {"name": name, "stdin": "\n".join(lines) + "\n",
            "description": description}


def _ordinary(rng, index):
    rows = []
    for _ in range(4):
        a = rng.randint(-1000, 1000)
        b = rng.randint(-1000, 1000)
        if b == 0:
            b = 1
        rows.append((a, b))
    return _case("ordinary divisions, no special case #%d" % index, rows)


def _near_zero_divisor(rng, index):
    rows = [
        (rng.randint(-1000, 1000), 0),
        (0, 0),
        (rng.randint(-1000, 1000), rng.choice([1, -1])),
    ]
    return _case("divisor of zero, plus neighbours #%d" % index, rows)


def _near_overflow(rng, index):
    rows = [
        (INT_MIN, -1),
        (INT_MIN, 1),
        (INT_MIN + 1, -1),
        (INT_MAX, -1),
    ]
    return _case("int.MinValue / -1 and the values right next to it #%d"
                 % index, rows,
                 "Only the exact pairing (INT_MIN, -1) overflows -- every "
                 "neighbour of it is Ok.")
